import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { RouterModule } from '@angular/router';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { ApiService, Skill } from '../../../../services/api';
import { Observable } from 'rxjs';

@Component({
  selector: 'app-skills',
  standalone: true,
  imports: [CommonModule, RouterModule, TranslateModule],
  templateUrl: './skills.component.html',
  styleUrl: './skills.component.css'
})
export class SkillsComponent implements OnInit {
  showFullProjects = false;
  $skills: Observable<Skill[]> = new Observable();

  constructor(
    private translate: TranslateService,
    private apiService: ApiService
  ) {}

  ngOnInit() {
    this.$skills = this.apiService.getSkills();
  }

  toggleFullProjects() {
    this.showFullProjects = !this.showFullProjects;
  }

  changeLang(language: string) {
    this.translate.use(language);
  }
}
<section id="skills-section">
  <div class="skills-card">
    <h2>{{'TECNOLOGIAS.TITLE'| translate}}</h2>
    <div class="icons-grid">
      <div class="skill-group" *ngFor="let skillGroup of $skills | async">
        <h3>{{ skillGroup.category }}</h3>
        <div class="skill-icons">
          <img *ngFor="let icon of skillGroup.icons" [src]="icon" [alt]="skillGroup.category" />
        </div>
      </div>
    </div>
  </div>
</section>
